{"command":"python3 - <<'PY'
import openpyxl, os, json
from openpyxl.utils import get_column_letter
src='/root/data/workbook.xlsx'
out='/root/output/result.xlsx'
errors=[]

wb_src = openpyxl.load_workbook(src, data_only=False)
orig_sheets = wb_src.sheetnames[:]
wb_src.close()

wb = openpyxl.load_workbook(out, data_only=False)
print('sheetnames:', wb.sheetnames)
if wb.sheetnames != orig_sheets:
    errors.append(f'Sheetnames changed: {wb.sheetnames} vs {orig_sheets}')
ws=wb['Task']

# Exact spot checks requested.
spot_cells=['H12','L17','H19','L24','H26','L31','H35','L40','H42','H47','H50']
print('spot checks data_only=False:')
for addr in spot_cells:
    v=ws[addr].value
    print(addr, repr(v))
    if not (isinstance(v,str) and v.startswith('=')):
        errors.append(f'{addr} is not a formula: {v!r}')
if '_xlfn.PERCENTILE.INC' not in ws['H47'].value:
    errors.append('H47 missing _xlfn.PERCENTILE.INC')
if ws['H42'].value != '=MIN(H35:H40)':
    errors.append(f'H42 unexpected: {ws["H42"].value!r}')
if 'SUMPRODUCT' not in ws['H50'].value:
    errors.append('H50 missing SUMPRODUCT')

# No target range blanks and all formulas start with =.
target_ranges = [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]
for r1,r2 in target_ranges:
    for r in range(r1,r2+1):
        for c in range(8,13):
            addr=f'{get_column_letter(c)}{r}'
            v=ws.cell(r,c).value
            if v in (None,''):
                errors.append(f'{addr} blank')
            elif not (isinstance(v,str) and v.startswith('=')):
                errors.append(f'{addr} not formula: {v!r}')

# Check intended formulas exactly for a few and generally for all lookup formulas.
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        got=ws.cell(r,c).value
        if got != expected:
            errors.append(f'{col}{r} lookup mismatch: {got!r} != {expected!r}')
for i in range(6):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+i}-{col}{19+i})/{col}{26+i}*100'
        got=ws.cell(35+i,c).value
        if got != expected:
            errors.append(f'{col}{35+i} net mismatch: {got!r} != {expected!r}')
for c in range(8,13):
    col=get_column_letter(c)
    expected=f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    got=ws.cell(50,c).value
    if got != expected:
        errors.append(f'{col}50 weighted mismatch: {got!r} != {expected!r}')

wb.close()

# data_only=True cache inspection (expected None okay)
wbv = openpyxl.load_workbook(out, data_only=True)
wsv = wbv['Task']
print('spot checks data_only=True cached values (None is acceptable if Excel has not recalculated):')
for addr in spot_cells:
    print(addr, repr(wsv[addr].value))
wbv.close()

if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('ERROR:', e)
    raise SystemExit(1)
print('VALIDATION PASSED: all target cells contain formulas, sheet count unchanged, requested spot checks OK')
